import Foundation

/// Atlas entries for the Music screens and the controls of its chrome. Music is the item after Podcasts in the top row (Cmd+8) and works only after first-run setup.
enum AtlasMusicScreens {
    private static func s(_ id: String, _ title: String, _ summary: String, _ path: [String], aliases: [String] = [], related: [String] = []) -> AtlasEntry {
        .make(id, .screen, title, summary, path: path, reach: .destination("music"), aliases: aliases, platforms: .mac, related: related)
    }
    private static func c(_ id: String, _ title: String, _ summary: String, _ path: [String]) -> AtlasEntry {
        .make(id, .control, title, summary, path: path, platforms: .mac)
    }

